create table if not exists notification_preferences(patient_id uuid primary key,has_smartphone boolean not null,preferred_channel varchar(60) not null,fallback_channel varchar(60));create table if not exists visit_patient_links(visit_id uuid primary key,patient_id uuid not null);create table if not exists processed_events(event_id uuid primary key,consumer_name varchar(120) not null,processed_at timestamptz not null);
